insert into public.posts
    (author_id, title, body, source_url, topic, tags, status, moderation_model, moderated_at)
values
(null, null, 'The observable universe is about 93 billion light-years across, even though it is only 13.8 billion years old, because space itself has been expanding the whole time light has been traveling.', 'NASA / Standard Cosmological Model', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Most of the universe''s mass-energy is invisible: roughly 68% is dark energy driving accelerated expansion, 27% is dark matter, and only about 5% is the ordinary matter that makes up stars, planets, and us.', 'Planck satellite measurements (ESA)', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Cosmic Microwave Background is leftover heat from the universe''s infancy, released about 380,000 years after the Big Bang when it cooled enough for light to travel freely for the first time.', 'COBE/WMAP/Planck mission data', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Galaxies are not scattered randomly; they form a cosmic web of filaments and clusters separated by vast empty voids, shaped by gravity acting on tiny density fluctuations from the early universe.', 'Sloan Digital Sky Survey', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'A supermassive black hole sits at the center of nearly every large galaxy, including our own Milky Way, where one called Sagittarius A* has a mass about 4 million times that of the Sun.', 'Event Horizon Telescope Collaboration', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Light from the Andromeda galaxy takes about 2.5 million years to reach us, meaning we see it as it looked long before modern humans existed.', 'Hubble Space Telescope data', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The universe''s expansion is accelerating, a discovery made by observing distant supernovae that appeared dimmer than expected, which earned the 2011 Nobel Prize in Physics.', 'Perlmutter', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Neutron stars are so dense that a teaspoon of their material would weigh about a billion tons on Earth.', 'NASA Goddard Space Flight Center', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'When two neutron stars collided in 2017, the event was detected both as gravitational waves and light, launching the era of ''multi-messenger astronomy.''', 'LIGO/Virgo Collaboration', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The night sky''s darkness is itself a cosmological clue, known as Olbers'' Paradox: in an infinite, unchanging universe every line of sight should end on a star, so the sky should blaze with light.', 'Heinrich Olbers', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Quasars are among the brightest objects in the universe, powered by supermassive black holes consuming gas so violently that they can outshine entire galaxies.', 'Maarten Schmidt', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Sun will eventually swell into a red giant, likely engulfing Mercury and Venus, before shedding its outer layers and leaving behind a white dwarf.', 'Stellar evolution models', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Space has no center and no edge in the way a balloon''s surface has no center point, which is why every galaxy sees every other galaxy moving away from it.', 'Friedmann-Lemaître-Robertson-Walker cosmological model', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Gravitational lensing, predicted by Einstein, lets astronomers use massive galaxy clusters as natural telescopes that bend and magnify the light of objects far behind them.', 'Albert Einstein', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The first stars in the universe, called Population III stars, were likely hundreds of times more massive than the Sun and burned out quickly, seeding space with heavier elements.', 'Theoretical astrophysics models', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Dark matter does not emit, absorb, or reflect light, so its existence is inferred only from its gravitational pull on visible matter and light.', 'Vera Rubin''s galaxy rotation studies', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Big Bang was not an explosion into empty space; it was the expansion of space itself, which is why asking ''what it expanded into'' is a common but mistaken framing.', 'Big Bang cosmology', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Pulsars are rapidly spinning neutron stars that sweep beams of radiation past Earth with clock-like regularity, first mistaken for signals from an alien civilization when discovered.', 'Jocelyn Bell Burnell', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Milky Way and Andromeda galaxies are on a collision course and will merge in about 4.5 billion years, though individual stars are unlikely to collide given the vast distances between them.', 'Hubble Space Telescope trajectory studies', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Cosmic inflation theory proposes the universe expanded exponentially in a fraction of a second after the Big Bang, smoothing it out and explaining why it looks so uniform on large scales.', 'Alan Guth', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Brown dwarfs are failed stars, too massive to be planets but too small to sustain the hydrogen fusion that powers true stars.', 'Astronomical classification', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The James Webb Space Telescope observes primarily in infrared light, letting it see through dust clouds and detect some of the earliest, most distant galaxies ever observed.', 'NASA/ESA/CSA JWST mission', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'A light-year measures distance, not time: it''s the distance light travels in one year, about 9.46 trillion kilometers.', 'Standard astronomical unit definition', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Saturn''s rings are made almost entirely of ice particles ranging from tiny grains to chunks the size of a house, and are surprisingly thin, only about 10 meters thick in places.', 'Cassini mission data', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Voyager 1, launched in 1977, is the most distant human-made object, having crossed into interstellar space in 2012 while still sending data back to Earth.', 'NASA Jet Propulsion Laboratory', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Black holes have no ''surface'' in the usual sense; the event horizon is simply the boundary beyond which nothing, not even light, can escape.', 'General Relativity', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The observable universe may be just a tiny patch of a much larger, possibly infinite universe, since we can only see as far as light has had time to travel to us.', 'Cosmological horizon theory', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Exoplanets are often detected by the ''transit method,'' measuring the tiny dip in a star''s brightness as a planet passes in front of it.', 'Kepler Space Telescope mission', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The most distant confirmed galaxy observed, JADES-GS-z14-0, existed just 290 million years after the Big Bang.', 'JWST Advanced Deep Extragalactic Survey', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Spacetime itself can ripple: gravitational waves from merging black holes stretch and squeeze space by less than the width of a proton as they pass Earth.', 'LIGO detection', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Hubble tension is a major unsolved problem in cosmology: two reliable methods of measuring the universe''s expansion rate give different answers, hinting at missing physics.', 'Ongoing cosmological research', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'A ''day'' on Venus is longer than its year; it takes 243 Earth days to rotate once but only 225 to orbit the Sun.', 'NASA planetary fact sheets', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Globular clusters are ancient, tightly packed balls of up to a million stars, some nearly as old as the universe itself.', 'Hubble Space Telescope stellar surveys', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The ''Great Attractor'' is a gravitational anomaly pulling our galaxy and thousands of others toward it at great speed, partly hidden from view by the Milky Way''s own disk.', 'Astrophysical observations', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Jupiter''s Great Red Spot is a storm larger than Earth that has raged for at least 190 years, though it has been shrinking in recent decades.', 'NASA Juno mission observations', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Time dilation near a black hole is extreme enough that someone orbiting close to it could experience minutes while years pass for distant observers, a real effect, not just movie fiction.', 'General Relativity predictions', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The universe is thought to be flat on large scales, meaning parallel lines of light stay parallel, based on precise measurements of the cosmic microwave background.', 'WMAP and Planck satellite data', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Most of the elements heavier than iron, including gold and platinum, were forged in the extreme collisions of neutron stars, not in ordinary stellar fusion.', 'Kilonova nucleosynthesis research', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Betelgeuse, a red supergiant star, is expected to explode as a supernova sometime in the next 100,000 years, an eyeblink on cosmic timescales.', 'Stellar evolution modeling', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Oort Cloud, a hypothesized shell of icy bodies surrounding the solar system, may extend nearly halfway to the nearest star.', 'Jan Oort', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Spiral galaxies like the Milky Way rotate in a way that doesn''t match visible matter alone, one of the strongest pieces of evidence for dark matter.', 'Vera Rubin rotation curve studies', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'A ''Hubble Deep Field'' image, staring at an apparently empty patch of sky for days, revealed thousands of previously unknown galaxies.', 'Hubble Space Telescope', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The cosmic distance ladder relies on different techniques at different scales, from measuring parallax for nearby stars to using supernovae as ''standard candles'' for distant galaxies.', 'Astronomical distance measurement methods', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Mercury has almost no atmosphere, so its surface temperature swings from about 430°C in the day to -180°C at night.', 'NASA MESSENGER mission data', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'A ''rogue planet'' is a planet that drifts through space unbound to any star, potentially more common in the galaxy than planets orbiting stars.', 'Microlensing survey studies', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Fermi Paradox asks why, given the vast number of stars and potentially habitable planets, we have found no evidence of other intelligent civilizations.', 'Enrico Fermi', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Neutron star collisions can produce ''kilonovae,'' explosive events bright enough to be seen across galaxies and responsible for much of the universe''s gold.', 'GW170817 observational campaign', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The Moon is slowly drifting away from Earth at about 3.8 centimeters per year, measured using laser reflectors left by Apollo astronauts.', 'Lunar Laser Ranging experiments', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'TRAPPIST-1, a small, cool star, hosts seven roughly Earth-sized planets, several within its habitable zone, making it one of the most studied planetary systems.', 'TRAPPIST and Spitzer telescope surveys', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'The universe''s ultimate fate is still debated, with scenarios ranging from endless cold expansion to a ''Big Rip'' where even atoms are torn apart.', 'Dark energy cosmological models', 'cosmology', array['cosmology'], 'approved', 'import:csv', now()),
(null, null, 'Octopuses have three hearts and blue blood; two hearts pump blood to the gills while the third pumps it to the rest of the body, and that third heart stops when the octopus swims.', 'Marine biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Human DNA is about 98.8% identical to chimpanzee DNA, a similarity that reflects our shared evolutionary ancestry roughly 6-7 million years ago.', 'Chimpanzee Genome Sequencing Consortium', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Tardigrades, microscopic ''water bears,'' can survive being frozen to near absolute zero, boiled, dried out for decades, and even exposed to the vacuum of space.', 'European Space Agency TARDIS experiment', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human body replaces most of its cells continuously; red blood cells last about 4 months, while skin cells are replaced roughly every 2-4 weeks.', 'Cell biology and physiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Some species of jellyfish, like Turritopsis dohrnii, can revert to an earlier life stage after reproducing, effectively making them biologically immortal under the right conditions.', 'Marine biology', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Bananas share about 60% of their DNA with humans, a reminder that many basic cellular processes are conserved across wildly different forms of life.', 'Comparative genomics research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'A single teaspoon of healthy soil can contain more microorganisms than there are people on Earth.', 'Soil microbiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Honeybees communicate the location of food sources to their hive through a precise ''waggle dance'' encoding both distance and direction relative to the sun.', 'Karl von Frisch', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The mitochondria in your cells were once free-living bacteria, absorbed by an ancestral cell roughly 1.5-2 billion years ago in a partnership called endosymbiosis.', 'Lynn Margulis', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Axolotls can regrow entire limbs, parts of their spinal cord, and even portions of their brain, making them a key model for regenerative medicine research.', 'Salamander regeneration studies', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Human babies are born with about 300 bones, many of which fuse together as they grow, leaving adults with 206.', 'Human skeletal development research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The blue whale, the largest animal to have ever lived, has a heart roughly the size of a small car and a tongue that can weigh as much as an elephant.', 'Marine mammal biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Some trees communicate and share nutrients through underground fungal networks nicknamed the ''wood wide web.''', 'Suzanne Simard', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Bats are the only mammals capable of sustained flight, and their wings are essentially modified hands with elongated finger bones supporting a skin membrane.', 'Chiropteran anatomy research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human gut contains trillions of bacteria, collectively called the microbiome, which help digest food, regulate immunity, and may even influence mood.', 'Human Microbiome Project', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Photosynthesis in plants splits water molecules to release oxygen, meaning nearly all the oxygen we breathe is a byproduct of plants pulling electrons from water.', 'Plant physiology and biochemistry research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Naked mole rats are nearly immune to cancer and can live up to 30 years, remarkably long for a rodent their size, making them a major focus of aging research.', 'Gerontology and cancer biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'A chameleon''s color changes are driven less by pigment and more by adjusting tiny crystal structures in their skin that reflect different wavelengths of light.', 'Nature journal', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Sharks have existed for over 400 million years, predating trees, which first appeared around 350 million years ago.', 'Paleontological fossil record', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human eye can distinguish about 10 million different colors, built from just three types of cone cells sensitive to different wavelengths of light.', 'Visual neuroscience research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Some species of ants practice agriculture, cultivating fungus gardens for food in a mutualistic relationship that predates human farming by tens of millions of years.', 'Myrmecology', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Starfish don''t have brains or blood; they move using a water vascular system and can regenerate entire limbs, sometimes even an entire body from a single arm.', 'Echinoderm biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Elephants are one of the few animals that can recognize themselves in a mirror, a sign of self-awareness shared with great apes, dolphins, and magpies.', 'Comparative cognition research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human genome contains roughly 20,000 protein-coding genes, far fewer than once expected, making up only about 1-2% of our total DNA.', 'Human Genome Project', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Platypuses are one of only five egg-laying mammal species, and males have venomous spurs on their hind legs potent enough to cause severe pain in humans.', 'Monotreme biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Coral reefs, despite covering less than 1% of the ocean floor, support roughly a quarter of all known marine species.', 'NOAA Coral Reef Conservation Program', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Giraffes have the same number of neck vertebrae as humans, seven, just dramatically elongated.', 'Mammalian comparative anatomy', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Some fungi, like the honey fungus in Oregon, can form a single organism spanning several square miles underground, making them among the largest living things.', 'Mycological research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Human muscles make up about 40% of total body weight, and the strongest muscle relative to its size is the masseter, used for chewing.', 'Human anatomy and physiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Dolphins sleep with only half their brain at a time, keeping one eye open to watch for predators and to resurface for air.', 'Marine mammal sleep research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Venus flytraps count: they only snap shut after two separate touches to their trigger hairs within about 20 seconds, preventing them from wasting energy on false alarms like raindrops.', 'Carnivorous plant physiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human heart beats roughly 100,000 times a day and about 2.5 billion times over an average lifetime.', 'Cardiovascular physiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Male seahorses, not females, carry and give birth to offspring, making them one of the only animal species where males become pregnant.', 'Marine biology', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Crows and other corvids can recognize individual human faces and hold what appears to be grudges for years against people who have wronged them.', 'University of Washington crow cognition research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human body contains enough iron to make a small nail, mostly concentrated in hemoglobin within red blood cells.', 'Human physiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Some species of frogs can survive being frozen solid during winter, with ice forming around their organs while a natural antifreeze protects their cells.', 'Wood frog cryobiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Lobsters don''t stop growing with age and show few signs of aging-related decline, though they aren''t actually immortal as is sometimes claimed; they die from exhaustion related to molting or disease.', 'Crustacean biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Mosquitoes are attracted to people partly based on carbon dioxide output, body heat, and certain skin bacteria, which is why some people get bitten more than others.', 'Medical entomology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The human appendix, once considered a useless evolutionary leftover, may actually serve as a reservoir for beneficial gut bacteria.', 'Duke University Medical Center research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Cats can make over 100 different vocal sounds, while dogs make around 10, though cats rarely meow at other cats, reserving it mainly for communicating with humans.', 'Animal behavior research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Komodo dragons can detect carrion from several miles away using their forked tongues to sample chemical particles in the air.', 'Herpetological research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Human fingerprints are fully formed by about 17 weeks of fetal development and remain unchanged, aside from scarring, for life.', 'Developmental biology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Penguins propose with pebbles in some species, presenting a carefully chosen stone to a potential mate as part of courtship.', 'Ornithological behavior studies', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The slowest-moving animal, the three-toed sloth, descends from its tree only about once a week, largely to defecate.', 'Mammalian behavior research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Woodpeckers'' brains are protected from the repeated impact of pecking by a combination of a spongy skull bone, a short duration of impact, and a small brain size relative to its surface area.', 'Avian biomechanics research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Some species of sea cucumbers expel their internal organs as a defense mechanism when threatened, then regrow them later.', 'Echinoderm defense mechanism research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Human twins can be fraternal, from two separate eggs, or identical, from one fertilized egg splitting, and identical twins do not have identical fingerprints.', 'Developmental genetics research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Bees can recognize individual human faces by learning to associate facial features in a pattern similar to how they would process complex flowers.', 'Insect cognition research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'A group of crows is called a ''murder,'' and they have been observed holding what resemble funeral gatherings around their dead.', 'Corvid behavioral ecology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'Camels store fat, not water, in their humps, which can be metabolized for energy during long periods without food.', 'Mammalian physiology research', 'biology', array['biology'], 'approved', 'import:csv', now()),
(null, null, 'The Great Library of Alexandria did not burn down in a single dramatic event; it declined gradually over centuries through funding cuts, political neglect, and several smaller fires.', 'Classical historiography', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Roman Empire never officially ''fell'' in 476 CE in the way often taught; its eastern half, the Byzantine Empire, continued for nearly another thousand years until 1453.', 'Byzantine historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Great Wall of China is not, as commonly claimed, visible to the naked eye from space; it is too narrow relative to its surroundings.', 'NASA astronaut observations and optics analysis', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Napoleon Bonaparte was not unusually short for his time; he stood about 5''7', 'average height for a Frenchman of that era', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Viking Age began with a documented raid on the monastery of Lindisfarne in 793 CE, an event that shocked Christian Europe for its violence against a sacred site.', 'Anglo-Saxon Chronicle records', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Cleopatra lived closer in time to the Moon landing in 1969 than to the construction of the Great Pyramid of Giza, which was built roughly 2,500 years before her birth.', 'Egyptological and chronological timelines', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The printing press, introduced by Johannes Gutenberg around 1440, didn''t just spread literacy; it standardized languages and accelerated the Reformation by making texts widely reproducible.', 'History of print culture scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Black Death killed an estimated 30-50% of Europe''s population between 1347 and 1351, reshaping labor markets and arguably hastening the end of feudalism.', 'Medieval demographic and economic history', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Ancient Rome had a functioning concrete recipe using volcanic ash that, in some structures, has proven more durable than much modern concrete, as seen in the still-standing Pantheon dome.', 'Materials science and Roman engineering research', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Code of Hammurabi, from around 1754 BCE, is one of the earliest known written legal codes, though it was not the first, predated by the Code of Ur-Nammu by centuries.', 'Mesopotamian historical and legal scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Ottoman Empire lasted over 600 years, from 1299 to 1922, making it one of the longest-lived empires in history.', 'Ottoman historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Christopher Columbus never set foot on what is now the continental United States; his voyages landed in the Caribbean, Central America, and South America.', 'Age of Exploration historical records', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Library of Congress''s claim to being the largest library in the world includes items beyond books: maps, manuscripts, recordings, and more, totaling tens of millions of items.', 'Library of Congress institutional records', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The French Revolution''s Reign of Terror, from 1793-1794, saw tens of thousands executed, often for vague charges of being ''enemies of the revolution.''', 'French revolutionary historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Genghis Khan''s Mongol Empire became the largest contiguous land empire in history, and ironically, its period of stability known as Pax Mongolica increased trade and cultural exchange along the Silk Road.', 'Mongol historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The ancient Egyptians mummified not just humans but animals, including cats, dogs, and crocodiles, sometimes as sacred offerings to specific gods.', 'Egyptological archaeological research', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Berlin Wall fell in 1989 largely due to a bureaucratic mistake: an East German official mistakenly announced during a press conference that new travel rules would take effect ''immediately.''', 'Cold War historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Ancient Sparta''s famed military society relied heavily on a brutally oppressed enslaved population called helots, who vastly outnumbered Spartan citizens.', 'Classical Greek historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Inca Empire, despite lacking a written language or the wheel for transport, built an extensive road system spanning roughly 25,000 miles across difficult Andean terrain.', 'Andean archaeological research', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Alexander the Great''s empire fractured almost immediately after his death in 323 BCE because he reportedly left no clear heir, having allegedly said his kingdom should go ''to the strongest.''', 'Hellenistic historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Salem witch trials of 1692-1693 resulted in the execution of 20 people, most by hanging, in a wave of hysteria later linked to factors including ergot poisoning theories and social tensions.', 'Colonial American historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'World War I began with the assassination of Archduke Franz Ferdinand in 1914, but the underlying causes involved decades of alliances, militarism, and nationalist tensions across Europe.', 'First World War historiography', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The ancient city of Pompeii was preserved almost intact under volcanic ash after Mount Vesuvius erupted in 79 CE, giving historians a rare snapshot of daily Roman life.', 'Pompeii archaeological excavation records', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Medieval European ''knights in shining armor'' fighting on muddy battlefields is largely a later romanticized image; plate armor was polished, but warfare was often brutal, chaotic, and unglamorous.', 'Medieval military historiography', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Magna Carta of 1215 was not originally about individual freedom for common people; it was a practical document limiting the English king''s power over rebellious barons.', 'Medieval English constitutional history', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Ancient Chinese civilization independently invented paper, gunpowder, the compass, and printing, four innovations that profoundly reshaped world history.', 'History of science and technology', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Trojan War, if it occurred at all, likely bears little resemblance to Homer''s account, though archaeological evidence suggests a real city at Hisarlik experienced destruction consistent with some elements of the story.', 'Classical archaeology', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Queen Elizabeth I of England never married, and her unmarried status, dubbed ''the Virgin Queen,'' became a deliberate political tool to avoid foreign entanglements through marriage.', 'Tudor historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The transatlantic slave trade forcibly transported an estimated 12.5 million Africans between the 16th and 19th centuries, with roughly 1.8 million dying during the Middle Passage.', 'Trans-Atlantic Slave Trade Database research', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The ancient Library of Baghdad''s House of Wisdom was a major center of translation and scholarship during the Islamic Golden Age, preserving and expanding on Greek, Persian, and Indian knowledge.', 'Islamic Golden Age historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Julius Caesar''s assassination in 44 BCE was carried out by a group of senators including Brutus, who feared Caesar''s growing, potentially monarchical power.', 'Roman republican historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Wright brothers'' first powered flight in 1903 lasted only 12 seconds and covered about 120 feet, shorter than the wingspan of some modern commercial airliners.', 'Smithsonian Institution aviation history records', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The ancient Minoan civilization on Crete may have been devastated by the eruption of Thera (Santorini) around 1600 BCE, an event some scholars connect to the Atlantis legend.', 'Aegean Bronze Age archaeological research', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Feudal Japan''s samurai code of bushido was formalized and romanticized largely after the era of actual samurai warfare had ended, during the peaceful Edo period.', 'Japanese historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Suez Canal, completed in 1869, dramatically shortened sea travel between Europe and Asia by eliminating the need to sail around Africa.', 'Maritime and economic history research', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Ancient Athenian democracy excluded women, enslaved people, and foreign residents, meaning only a minority of the population, adult male citizens, could actually vote.', 'Classical Athenian historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Hundred Years'' War between England and France actually lasted 116 years, from 1337 to 1453, named for its approximate rather than exact duration.', 'Medieval European historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Marie Antoinette likely never said ''Let them eat cake''; the phrase predates her and was likely attributed to her later to symbolize aristocratic indifference.', 'French historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The ancient city of Carthage was so thoroughly destroyed by Rome in 146 BCE at the end of the Third Punic War that, according to legend, its fields were salted, though historians debate whether this actually happened.', 'Punic Wars historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Apollo Guidance Computer that helped land astronauts on the Moon in 1969 had less processing power than a modern pocket calculator.', 'History of computing and NASA archives', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Ancient Babylon''s Hanging Gardens, one of the Seven Wonders of the Ancient World, may never have existed in Babylon at all; some historians believe the accounts actually describe gardens in Nineveh.', 'Mesopotamian archaeological scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Renaissance, often framed as a sudden European ''rebirth,'' built heavily on knowledge preserved and expanded by Islamic scholars during centuries when much of that knowledge had been lost in Western Europe.', 'History of science', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The first recorded Olympic Games were held in 776 BCE in Olympia, Greece, originally as a religious festival honoring Zeus.', 'Classical Greek historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The Gutenberg Bible, printed around 1455, was not actually the first printed book; woodblock printing had existed in East Asia for centuries prior.', 'History of printing scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The ancient Phoenicians developed one of the first widely adopted alphabets, which, through Greek and Latin adaptation, became the ancestor of most modern Western writing systems.', 'History of writing systems scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Benjamin Franklin never actually flew a kite into a thunderstorm in the reckless way popularly depicted; contemporary accounts suggest his experiment, if performed as described, used a silk kite with significant safety precautions.', 'American colonial historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'The fall of Constantinople in 1453 to Ottoman forces is often cited as marking the end of the medieval period and contributed to driving Greek scholars westward, fueling the European Renaissance.', 'Byzantine and Ottoman historical scholarship', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'Ancient Rome''s bread and circuses policy involved regularly distributing free grain and staging public entertainment, partly as a deliberate strategy to pacify and control the urban poor.', 'Roman social and political historiography', 'history', array['history'], 'approved', 'import:csv', now()),
(null, null, 'If you dropped a feather and a hammer on the Moon, they would hit the ground at the same time, as Apollo 15 astronaut David Scott demonstrated live in 1971, confirming that gravity accelerates all objects equally in a vacuum.', 'NASA Apollo 15 mission records', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Nothing can travel faster than light in a vacuum, about 299,792 kilometers per second, a cosmic speed limit built into the structure of spacetime itself.', 'Einstein''s Special Relativity', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'E=mc² means mass and energy are interchangeable; the tiny mass lost in nuclear reactions converts into enormous amounts of energy, explaining both nuclear power and the Sun''s output.', 'Einstein''s mass-energy equivalence', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Quantum entanglement links particles so that measuring one instantly correlates with the state of the other, regardless of distance, a phenomenon Einstein skeptically called ''spooky action at a distance.''', 'Quantum mechanics research', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Absolute zero, -273.15°C, is the temperature at which atomic motion theoretically stops entirely, though it has never been fully reached in any experiment.', 'Thermodynamics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Sound cannot travel through the vacuum of space because it requires a medium, like air or water, to transmit its vibrations.', 'Acoustic physics principles', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A black hole''s gravity is so strong that even light cannot escape once it crosses the event horizon, the boundary defined by the point of no return.', 'General Relativity', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Electrons do not orbit an atomic nucleus like planets around a sun; they exist in probabilistic clouds called orbitals, where their exact position cannot be precisely known.', 'Quantum mechanics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Heisenberg Uncertainty Principle states that the more precisely you know a particle''s position, the less precisely you can know its momentum, and vice versa, a fundamental limit, not a measurement flaw.', 'Werner Heisenberg', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Superconductors can conduct electricity with zero resistance when cooled below a critical temperature, allowing currents to theoretically flow forever without energy loss.', 'Low-temperature physics research', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A rainbow forms because water droplets refract, reflect, and disperse sunlight, splitting it into its component wavelengths, which is why no two people ever see exactly the same rainbow.', 'Optical physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Time passes slightly slower for GPS satellites relative to observers on Earth due to both their speed and weaker gravity, an effect engineers must correct for or satellite navigation would drift by kilometers daily.', 'General and Special Relativity applications', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Double-slit experiments show that light and matter behave as both particles and waves, with the act of measurement itself seeming to influence which behavior is observed.', 'Quantum mechanics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A nuclear reactor and a nuclear bomb rely on the same basic fission reaction, but a reactor sustains it in a controlled, slow chain reaction while a bomb''s reaction is explosively rapid and uncontrolled.', 'Nuclear physics engineering principles', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Friction, not gravity, is what actually stops a rolling ball on a flat surface; in a true vacuum with no friction, the ball would roll indefinitely.', 'Classical mechanics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The color of a star indicates its temperature: blue stars are hottest, red stars are coolest, the opposite of the common association of red with heat.', 'Stellar spectroscopy and classification', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Magnetism and electricity are two aspects of the same fundamental force, electromagnetism, unified mathematically by James Clerk Maxwell in the 19th century.', 'James Clerk Maxwell''s equations', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A pendulum''s swing period depends only on its length and gravity, not on the weight of the bob, a principle Galileo reportedly noticed while watching a swinging lamp.', 'Galileo Galilei', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Lightning is hotter than the surface of the Sun, briefly reaching temperatures around 30,000 Kelvin as it superheats the surrounding air, causing the explosive expansion heard as thunder.', 'Atmospheric physics research', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The reason the sky is blue is that shorter blue wavelengths of sunlight scatter more than other colors when they hit molecules in the atmosphere, a phenomenon called Rayleigh scattering.', 'Lord Rayleigh', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Objects in free fall are actually weightless, which is why astronauts in orbit float; they aren''t escaping gravity, they''re continuously falling around the Earth.', 'Orbital mechanics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The triple point of water, 0.01°C at a specific pressure, is the exact condition where ice, liquid water, and water vapor coexist in equilibrium.', 'Thermodynamic phase diagrams', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Radioactive decay is fundamentally random for any individual atom, but statistically predictable for large numbers, which is the basis for radiometric dating techniques like carbon-14 dating.', 'Nuclear physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A Foucault pendulum demonstrates Earth''s rotation directly: as it swings, its plane of motion appears to slowly rotate relative to the ground beneath it.', 'Léon Foucault', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Neutrinos are so weakly interacting that trillions pass through your body every second without you noticing, and most pass straight through the entire Earth.', 'Particle physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Quantum tunneling allows particles to pass through energy barriers they classically shouldn''t be able to cross, a phenomenon essential to the nuclear fusion powering the Sun.', 'Quantum mechanics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The speed of sound varies with medium: it travels roughly four times faster through water than through air, and even faster through solids like steel.', 'Acoustic physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Antimatter is identical to ordinary matter but with opposite electric charge, and when matter and antimatter meet, they annihilate each other, converting their mass entirely into energy.', 'Particle physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Casimir effect shows that even a vacuum isn''t truly empty; two uncharged metal plates placed extremely close together experience a measurable attractive force due to quantum fluctuations.', 'Hendrik Casimir', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A gyroscope resists changes to its orientation due to angular momentum, which is why spinning tops stay upright and bicycles are easier to balance while moving.', 'Classical mechanics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Doppler effect explains why an ambulance siren sounds higher-pitched as it approaches and lower-pitched as it moves away, caused by sound waves compressing and stretching relative to the listener.', 'Christian Doppler', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Superfluidity allows certain liquids, like helium cooled near absolute zero, to flow without any viscosity at all, even climbing up and over the walls of their container.', 'Low-temperature quantum physics research', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The reason ice floats is that water is one of the few substances that becomes less dense as it freezes, due to the hydrogen-bonded crystal structure ice forms.', 'Molecular physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A photon has no mass and no rest frame; from a photon''s own ''perspective,'' if it had one, it would experience zero time between its emission and absorption.', 'Special Relativity', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The strong nuclear force, one of the four fundamental forces, binds protons and neutrons together in an atomic nucleus despite the protons'' mutual electrical repulsion.', 'Particle physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Chaos theory shows that tiny differences in initial conditions can lead to vastly different outcomes in complex systems, famously illustrated by the idea that a butterfly''s wings could theoretically influence a distant storm.', 'Edward Lorenz', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Mpemba effect describes the counterintuitive observation that, under certain conditions, hot water can freeze faster than cold water, a phenomenon still debated among physicists.', 'Erasto Mpemba observations', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A laser produces light that is coherent, meaning all its waves are in phase and traveling in the same direction, unlike the scattered light from an ordinary bulb.', 'Laser physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Standard Model of particle physics describes 17 fundamental particles, including quarks, leptons, and the Higgs boson, confirmed experimentally in 2012.', 'CERN', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Sound waves can be used to levitate small objects through acoustic levitation, using precisely tuned standing waves to counteract gravity.', 'Acoustic physics research', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A rainbow''s order of colors, red on the outside and violet on the inside, is reversed in a secondary rainbow, caused by an additional internal reflection inside the water droplets.', 'Optical physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The concept of ''absolute motion'' doesn''t exist in physics; all motion is relative to a chosen frame of reference, a principle central to both Galilean and Einsteinian relativity.', 'Galileo Galilei and Einstein''s relativity principles', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Gravitational waves, ripples in spacetime predicted by Einstein in 1916, were not directly detected until a century later, in 2015, from colliding black holes over a billion light-years away.', 'LIGO Collaboration', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'A material''s color under white light is determined by which wavelengths it reflects, while the wavelengths it absorbs are converted mostly into heat.', 'Optical and thermal physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Coriolis effect, caused by Earth''s rotation, deflects moving air and water, curving hurricanes counterclockwise in the Northern Hemisphere and clockwise in the Southern Hemisphere.', 'Atmospheric and fluid dynamics physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Superconducting magnets, cooled with liquid helium, are what allow MRI machines to generate the powerful, stable magnetic fields needed for detailed medical imaging.', 'Medical physics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The ''twin paradox'' in relativity describes how a twin who travels near light speed and returns will have aged less than the twin who stayed on Earth, a real, experimentally supported effect, not a true paradox.', 'Special Relativity thought experiment', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Water''s high specific heat capacity, the energy required to raise its temperature, helps regulate Earth''s climate by allowing oceans to absorb and release heat slowly.', 'Thermodynamics', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'Plasma, often called the fourth state of matter, makes up over 99% of the visible universe, found in stars, lightning, and neon signs.', 'Plasma physics research', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Large Hadron Collider accelerates particles to 99.9999991% the speed of light, making it the most powerful and complex scientific instrument ever built.', 'CERN technical specifications', 'physics', array['physics'], 'approved', 'import:csv', now()),
(null, null, 'The Ship of Theseus thought experiment asks whether an object that has had all its components replaced remains fundamentally the same object, probing deep questions about identity over time.', 'Classical Greek philosophy', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'René Descartes'' famous conclusion ''I think, therefore I am'' was his attempt to find one undeniable truth by doubting literally everything else he could possibly doubt.', 'René Descartes', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Plato''s Allegory of the Cave describes prisoners mistaking shadows on a wall for reality, a metaphor for how most people mistake appearances for deeper truths.', 'Plato', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The Trolley Problem, a classic ethical dilemma, asks whether it''s morally justified to divert a runaway trolley to kill one person instead of five, probing the difference between action and inaction.', 'Philippa Foot', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Nihilism holds that life has no inherent meaning, purpose, or intrinsic value, a position often associated with, though not originated by, Friedrich Nietzsche.', 'Friedrich Nietzsche''s philosophical works', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Stoicism teaches that while we can''t control external events, we can control our judgments and reactions to them, a framework that influenced both ancient Rome and modern cognitive therapy.', 'Epictetus', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''is-ought problem,'' identified by David Hume, points out that you cannot logically derive a statement about what should be from statements about what simply is.', 'David Hume', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Existentialism holds that existence precedes essence, meaning humans first exist and only later, through their choices, define their own nature and purpose.', 'Jean-Paul Sartre', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The Chinese Room thought experiment questions whether a system that convincingly manipulates symbols to pass as intelligent truly ''understands'' anything at all.', 'John Searle', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Zeno''s paradoxes, like Achilles and the Tortoise, seemingly prove that motion is impossible by dividing distance into infinitely smaller segments, a puzzle not fully resolved until the development of calculus.', 'Zeno of Elea', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Utilitarianism judges the morality of an action by its consequences, specifically whether it maximizes overall happiness or well-being for the greatest number of people.', 'Jeremy Bentham', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Immanuel Kant''s categorical imperative argues that an action is moral only if you could will it to become a universal law applicable to everyone.', 'Immanuel Kant', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''problem of evil'' asks how an all-powerful, all-knowing, and perfectly good God could allow suffering to exist, a central challenge in the philosophy of religion.', 'Epicurus', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Solipsism is the philosophical position that only one''s own mind can be known to exist with certainty, treating everything else as potentially an illusion.', 'Epistemological philosophy', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''veil of ignorance'' thought experiment asks us to design a just society without knowing what position, rich or poor, we would personally occupy within it.', 'John Rawls', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Confucianism emphasizes social harmony through defined roles, duties, and respect, particularly filial piety toward parents and elders, as the foundation for a well-ordered society.', 'Confucius', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The hard problem of consciousness asks why physical processes in the brain give rise to subjective experience at all, rather than simply processing information unconsciously.', 'David Chalmers', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Occam''s Razor suggests that, among competing explanations, the one requiring the fewest assumptions is usually preferable, though it''s a heuristic, not a guarantee of truth.', 'William of Ockham', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The Buddhist concept of anatta, or ''non-self,'' argues that there is no permanent, unchanging self, only a continuously changing stream of thoughts and sensations.', 'Buddhist philosophy', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Thomas Hobbes argued that without a strong governing authority, human life in a ''state of nature'' would be ''solitary, poor, nasty, brutish, and short.''', 'Thomas Hobbes', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''ship of fools'' metaphor, used by multiple philosophers across history, criticizes a society governed by those unqualified or unfit to lead, drifting without real direction.', 'Plato and later Renaissance philosophical traditions', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Compatibilism argues that free will and determinism aren''t necessarily contradictory, as long as ''free'' actions are simply those free from external coercion, regardless of underlying causality.', 'David Hume and later compatibilist philosophy', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Simone de Beauvoir argued that ''one is not born, but rather becomes, a woman,'' proposing that gender is substantially shaped by social construction rather than biology alone.', 'Simone de Beauvoir', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The Euthyphro Dilemma asks whether something is good because God commands it, or whether God commands it because it is already good, challenging simple divine command theories of morality.', 'Plato', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Epicureanism, often misrepresented as mere hedonism, actually advocated for modest, simple pleasures and the avoidance of pain as the path to a tranquil, contented life.', 'Epicurus', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Friedrich Nietzsche''s concept of the ''Übermensch'' describes an individual who creates their own values rather than passively accepting inherited religious or societal morality.', 'Friedrich Nietzsche', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The philosophical zombie thought experiment imagines a being physically identical to a human but lacking any subjective inner experience, raising questions about what consciousness actually requires.', 'David Chalmers', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Taoism''s concept of ''wu wei,'' or ''effortless action,'' emphasizes aligning with the natural flow of things rather than forcing outcomes through excessive struggle or control.', 'Laozi', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The Ship of Theseus has a modern twin problem, the ''Grandfather''s Axe,'' which asks if an axe with a replaced handle and later a replaced head is still the same axe.', 'Classical identity philosophy', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'John Locke argued the mind at birth is a ''tabula rasa,'' or blank slate, shaped entirely by experience rather than innate ideas.', 'John Locke', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Existential absurdism, as described by Albert Camus, holds that the human search for meaning inherently conflicts with an indifferent, meaningless universe, creating the ''absurd.''', 'Albert Camus', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''paradox of the heap'' (sorites paradox) questions at what exact point removing individual grains of sand from a heap causes it to stop being a ''heap'' at all.', 'Eubulides of Miletus', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Georg Hegel''s dialectical method describes historical and intellectual progress as a process of thesis, antithesis, and synthesis, continually resolving contradictions into higher understanding.', 'Georg Wilhelm Friedrich Hegel', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''brain in a vat'' thought experiment questions whether we could ever truly know if our entire perceived reality is simply an elaborate simulation fed directly into our brain.', 'Hilary Putnam', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Virtue ethics, associated with Aristotle, focuses less on specific rules or consequences and more on cultivating good character traits that lead to a flourishing life.', 'Aristotle', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''is-ought gap'' remains one of the most persistent challenges in moral philosophy, questioning whether ethics can ever be derived purely from factual, scientific observation.', 'Metaethics scholarship', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Baruch Spinoza argued that God and nature are fundamentally the same single substance, a view called pantheism that was controversial enough to get him excommunicated from his Jewish community.', 'Baruch Spinoza', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''paradox of hedonism'' suggests that directly and exclusively pursuing pleasure as a goal often makes it harder to actually achieve lasting happiness.', 'Henry Sidgwick', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Arthur Schopenhauer argued that an underlying, blind, striving ''Will'' drives all existence, making suffering an unavoidable, fundamental feature of life itself.', 'Arthur Schopenhauer', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''Ship of State'' metaphor, used since Plato, compares governing a nation to piloting a ship, requiring real skill and knowledge rather than popularity alone.', 'Plato', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Michel Foucault argued that power operates not just through overt force but through subtle social institutions, knowledge systems, and discourse that shape what we consider ''normal.''', 'Michel Foucault', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The ''ethics of care'' philosophical approach, developed largely by feminist philosophers, emphasizes relationships, empathy, and context over abstract, impartial moral rules.', 'Carol Gilligan', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'Søren Kierkegaard argued that true faith requires a ''leap'' beyond rational justification entirely, famously illustrated through his analysis of Abraham''s willingness to sacrifice Isaac.', 'Søren Kierkegaard', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
(null, null, 'The Ship of Theseus debate extends directly into modern questions about personal identity: are you the ''same'' person you were as a child, given that virtually all your cells have been replaced?', 'Personal identity philosophy', 'philosophy', array['philosophy'], 'approved', 'import:csv', now()),
